"c","validated":true,"definition":"CHECK (declares_cnpj)"},{"name":"commercial_orders_direct_pix_approval_actor_check","type":"c","validated":true,"definition":"CHECK (((payment_method <> ''direct_pix''::text) OR (status <> ''payment_approved''::text) OR (payment_approved_by IS NOT NULL)))"},{"name":"commercial_orders_direct_pix_proof_check","type":"c","validated":true,"definition":"CHECK (((payment_method <> ''direct_pix''::text) OR (status = ANY (ARRAY[''awaiting_payment''::text, ''cancelled''::text])) OR ((proof_reference IS NOT NULL) AND (length(btrim(proof_reference)) > 0) AND (proof_received_at IS NOT NULL) AND (proof_received_by IS NOT NULL))))"},{"name":"commercial_orders_discount_matches","type":"c","validated":true,"definition":"CHECK ((((billing_period = ''monthly''::text) AND (discount_percent = 0)) OR ((billing_period = ''semiannual_upfront''::text) AND (discount_percent = 5)) OR ((billing_period = ''annual_upfront''::text) AND (discount_percent = 12))))"},{"name":"commercial_orders_external_ref_key","type":"u","validated":true,"definition":"UNIQUE (external_ref)"},{"name":"commercial_orders_origin_check","type":"c","validated":true,"definition":"CHECK ((origin = ANY (ARRAY[''assisted''::text, ''self_service''::text])))"},{"name":"commercial_orders_paid_business_check","type":"c","validated":true,"definition":"CHECK (((status <> ''payment_approved''::text) OR (business_id IS NOT NULL)))"},{"name":"commercial_orders_payment_approved_by_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (payment_approved_by) REFERENCES profiles(id) ON DELETE SET NULL"},{"name":"commercial_orders_payment_attempt_count_check","type":"c","validated":true,"definition":"CHECK (((payment_attempt_count >= 0) AND (payment_attempt_count <= 3)))"},{"name":"commercial_orders_payment_method_check","type":"c","validated":true,"definition":"CHECK ((payment_method = ANY (ARRAY[''direct_pix''::text, ''asaas_pix''::text, ''asaas_card''::text])))"},{"name":"commercial_orders_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"commercial_orders_proof_received_by_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (proof_received_by) REFERENCES profiles(id) ON DELETE SET NULL"},{"name":"commercial_orders_provider_card_flow_check","type":"c","validated":true,"definition":"CHECK ((provider_card_flow = ANY (ARRAY[''direct''::text, ''initial_3ds''::text])))"},{"name":"commercial_orders_provider_charge_id_key","type":"u","validated":true,"definition":"UNIQUE (provider_charge_id)"},{"name":"commercial_orders_provider_checkout_id_key","type":"u","validated":true,"definition":"UNIQUE (provider_checkout_id)"},{"name":"commercial_orders_provider_subscription_id_key","type":"u","validated":true,"definition":"UNIQUE (provider_subscription_id)"},{"name":"commercial_orders_sells_by_whatsapp_check","type":"c","validated":true,"definition":"CHECK (sells_by_whatsapp)"},{"name":"commercial_orders_status_check","type":"c","validated":true,"definition":"CHECK ((status = ANY (ARRAY[''awaiting_payment''::text, ''proof_received''::text, ''payment_approved''::text, ''cancelled''::text])))"},{"name":"commercial_orders_total_cents_check","type":"c","validated":true,"definition":"CHECK ((total_cents > 0))"},{"name":"commercial_orders_total_matches","type":"c","validated":true,"definition":"CHECK ((total_cents = (unit_count *\nCASE billing_period\n    WHEN ''monthly''::text THEN 50000\n    WHEN ''semiannual_upfront''::text THEN 285000\n    ELSE 528000\nEND)))"},{"name":"commercial_orders_unit_count_check","type":"c","validated":true,"definition":"CHECK ((unit_count > 0))"},{"name":"commercial_orders_unit_price_cents_check","type":"c","validated":true,"definition":"CHECK ((unit_price_cents = 50000))"}]},{"acl":"{postgres=arwdDxtm/postgres,service_role=arw/postgres}","rls":true,"name":"commercial_payment_email_outbox","owner":"postgres","columns":[{"acl":null,"name":"id","type":"uuid","default":"gen_random_uuid()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"order_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"provider_charge_id","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"payload","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"status","type":"text","default":"''queued''::text","identity":"","not_null":true,"generated":""},{"acl":null,"name":"provider_message_id","type":"text","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"updated_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"indexes":[{"name":"commercial_payment_email_outbox_order_id_provider_charge_id_key","definition":"CREATE UNIQUE INDEX commercial_payment_email_outbox_order_id_provider_charge_id_key ON public.commercial_payment_email_outbox USING btree (order_id, provider_charge_id)","constraint_owned":true},{"name":"commercial_payment_email_outbox_pkey","definition":"CREATE UNIQUE INDEX commercial_payment_email_outbox_pkey ON public.commercial_payment_email_outbox USING btree (id)","constraint_owned":true}],"policies":null,"triggers":null,"force_rls":false,"constraints":[{"name":"commercial_payment_email_outbox_check","type":"c","validated":true,"definition":"CHECK (((status <> ''accepted''::text) OR (provider_message_id IS NOT NULL)))"},{"name":"commercial_payment_email_outbox_order_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (order_id) REFERENCES commercial_orders(id)"},{"name":"commercial_payment_email_outbox_order_id_provider_charge_id_key","type":"u","validated":true,"definition":"UNIQUE (order_id, provider_charge_id)"},{"name":"commercial_payment_email_outbox_payload_check","type":"c","validated":true,"definition":"CHECK ((jsonb_typeof(payload) = ''object''::text))"},{"name":"commercial_payment_email_outbox_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"commercial_payment_email_outbox_provider_charge_id_check","type":"c","validated":true,"definition":"CHECK ((provider_charge_id ~ ''^pay_[A-Za-z0-9]+$''::text))"},{"name":"commercial_payment_email_outbox_status_check","type":"c","validated":true,"definition":"CHECK ((status = ANY (ARRAY[''queued''::text, ''sending''::text, ''accepted''::text, ''review''::text])))"}]},{"acl":"{postgres=arwdDxtm/postgres,service_role=ar/postgres}","rls":true,"name":"commercial_payment_events","owner":"postgres","columns":[{"acl":null,"name":"provider_event_id","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"order_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"provider_charge_id","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"provider_subscription_id","type":"text","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"due_date","type":"date","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"event_type","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"amount_cents","type":"integer","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"received_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"indexes":[{"name":"commercial_payment_events_order_idx","definition":"CREATE INDEX commercial_payment_events_order_idx ON public.commercial_payment_events USING btree (order_id, received_at DESC)","constraint_owned":false},{"name":"commercial_payment_events_pkey","definition":"CREATE UNIQUE INDEX commercial_payment_events_pkey ON public.commercial_payment_events USING btree (provider_event_id)","constraint_owned":true}],"policies":null,"triggers":null,"force_rls":false,"constraints":[{"name":"commercial_payment_events_amount_cents_check","type":"c","validated":true,"definition":"CHECK ((amount_cents > 0))"},{"name":"commercial_payment_events_event_type_check","type":"c","validated":true,"definition":"CHECK ((event_type = ANY (ARRAY[''PAYMENT_CREATED''::text, ''PAYMENT_UPDATED''::text, ''PAYMENT_OVERDUE''::text, ''PAYMENT_CONFIRMED''::text, ''PAYMENT_RECEIVED''::text, ''PAYMENT_AWAITING_RISK_ANALYSIS''::text, ''PAYMENT_APPROVED_BY_RISK_ANALYSIS''::text, ''PAYMENT_REPROVED_BY_RISK_ANALYSIS''::text, ''PAYMENT_AUTHORIZED''::text, ''PAYMENT_CREDIT_CARD_CAPTURE_REFUSED''::text, ''PAYMENT_CREDIT_CARD_THREE_D_SECURE_CHALLENGE_FAILED''::text, ''PAYMENT_REFUND_IN_PROGRESS''::text, ''PAYMENT_PARTIALLY_REFUNDED''::text, ''PAYMENT_REFUNDED''::text, ''PAYMENT_CHARGEBACK_REQUESTED''::text, ''PAYMENT_CHARGEBACK_DISPUTE''::text, ''PAYMENT_AWAITING_CHARGEBACK_REVERSAL''::text])))"},{"name":"commercial_payment_events_order_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (order_id) REFERENCES commercial_orders(id) ON DELETE RESTRICT"},{"name":"commercial_payment_events_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (provider_event_id)"},{"name":"commercial_payment_events_provider_charge_id_check","type":"c","validated":true,"definition":"CHECK ((provider_charge_id ~ ''^pay_[A-Za-z0-9]+$''::text))"}]}],"functions":[{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"aprovar_pagamento_api_self_service","owner":"postgres","signature":"aprovar_pagamento_api_self_service(uuid,text,text,text,text,text,integer,date)","definition":"CREATE OR REPLACE FUNCTION public.aprovar_pagamento_api_self_service(p_order_id uuid, p_charge_id text, p_subscription_id text, p_customer_id text, p_event_id text, p_event_type text, p_total_cents integer, p_due_date date)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_order public.commercial_orders%rowtype;\n  v_event_order uuid;\nbegin\n  if p_order_id is null or p_charge_id is null or p_charge_id !~ ''^pay_[A-Za-z0-9]+$''\n      or p_customer_id is null or p_customer_id !~ ''^cus_[A-Za-z0-9]+$''\n      or p_event_id is null or length(p_event_id) < 5\n      or p_event_type not in (''PAYMENT_CONFIRMED'', ''PAYMENT_RECEIVED'')\n      or p_total_cents is null or p_total_cents < 1 then return false; end if;\n\n  select * into v_order from public.commercial_orders\n    where id = p_order_id for update;\n  if not found or v_order.origin <> ''self_service''\n      or v_order.provider_checkout_id is not null\n      or v_order.provider_customer_id is distinct from p_customer_id\n      or v_order.total_cents <> p_total_cents then return false; end if;\n\n  if v_order.billing_period = ''monthly'' then\n    if v_order.payment_method <> ''asaas_card''\n        or p_subscription_id is null\n        or v_order.provider_subscription_id is distinct from p_subscription_id\n        or v_order.provider_first_due_date is distinct from p_due_date\n        or (v_order.provider_charge_id is not null\n            and v_order.provider_charge_id <> p_charge_id) then return false; end if;\n  elsif v_order.provider_subscription_id is not null\n      or p_subscription_id is not null\n      or v_order.provider_charge_id is distinct from p_charge_id then\n    return false;\n  end if;\n\n\r\n  if exists(select 1 from public.commercial_payment_events e\r\n      where e.order_id=p_order_id and e.provider_charge_id=p_charge_id\r\n        and public.evento_asaas_impede_confirmacao(e.event_type)) then return false; end if;\r\n  select order_id into v_event_order from public.commercial_events\n    where source = ''asaas'' and external_event_id = p_event_id;\n  if found then return v_event_order = p_order_id; end if;\n  if v_order.status = ''payment_approved'' then return true; end if;\n  if v_order.status <> ''awaiting_payment'' then return false; end if;\n\n  insert into public.commercial_events(order_id, source, external_event_id, event_type)\n    values (p_order_id, ''asaas'', p_event_id, p_event_type);\n  update public.commercial_orders\n    set status = ''payment_approved'', payment_approved_at = now(),\n        provider_charge_id = p_charge_id, updated_at = now()\n    where id = p_order_id;\n  return true;\nend;\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"aprovar_pix_assistido","owner":"postgres","signature":"aprovar_pix_assistido(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.aprovar_pix_assistido(p_order_id uuid, p_operator_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare v_order public.commercial_orders%rowtype;\nbegin\n  if p_operator_id is null then raise exception ''operador obrigatorio''; end if;\n  select * into v_order from public.commercial_orders\n    where id = p_order_id and payment_method = ''direct_pix'' for update;\n  if not found then raise exception ''pedido nao encontrado''; end if;\n  if v_order.status = ''payment_approved'' then return true; end if;\n  if v_order.status <> ''proof_received'' or v_order.business_id is null\n      or v_order.proof_reference is null then\n    raise exception ''comprovante e negocio obrigatorios'';\n  end if;\n  update public.commercial_orders set status = ''payment_approved'',\n    payment_approved_at = now(), payment_approved_by = p_operator_id,\n    updated_at = now() where id = p_order_id;\n  insert into public.commercial_events(order_id, source, external_event_id,\n    event_type, actor_profile_id)\n    values (p_order_id, ''operator'', ''approve:'' || p_order_id::text,\n      ''pix_aprovado_por_operador'', p_operator_id);\n  return true;\nend;\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"checkout_producao_schema_v1","owner":"postgres","signature":"checkout_producao_schema_v1()","definition":"CREATE OR REPLACE FUNCTION public.checkout_producao_schema_v1()\n RETURNS integer\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''''\nAS $function$\ndeclare\n  t text;\n  sig text;\n  f oid;\n  v_access record;\n  v_role text;\n  v_privilege text;\nbegin\n  foreach t in array array[''businesses'',''commercial_orders'',''commercial_order_units'',\n    ''commercial_events'',''commercial_payment_events'',''commercial_payment_email_outbox'',\n    ''checkout_3ds_context'',''checkout_security_attempts''] loop\n    if not exists (select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n\n      on n.oid=c.relnamespace where n.nspname=''public'' and c.relname=t\n      and c.relkind=''r'' and c.relrowsecurity) then return 0; end if;\n    if not pg_catalog.has_table_privilege(''service_role'',''public.''||t,''SELECT'') then return 0; end if;\n  end loop;\n  -- has_table_privilege com lista de privilegios usa ANY. Cada permissao\n  -- exigida pelos grants acima precisa passar individualmente (ALL).\n  for v_access in select * from (values\n    (''businesses'',''SELECT''),(''businesses'',''INSERT''),(''businesses'',''UPDATE''),\n    (''commercial_orders'',''SELECT''),(''commercial_orders'',''INSERT''),(''commercial_orders'',''UPDATE''),\n    (''commercial_order_units'',''SELECT''),(''commercial_order_units'',''INSERT''),(''commercial_order_units'',''UPDATE''),\n    (''commercial_events'',''SELECT''),(''commercial_events'',''INSERT''),\n    (''commercial_payment_events'',''SELECT''),(''commercial_payment_events'',''INSERT''),\n    (''commercial_payment_email_outbox'',''SELECT''),(''commercial_payment_email_outbox'',''INSERT''),(''commercial_payment_email_outbox'',''UPDATE''),\n    (''checkout_3ds_context'',''SELECT''),(''checkout_3ds_context'',''INSERT''),(''checkout_3ds_context'',''UPDATE''),(''checkout_3ds_context'',''DELETE''),\n    (''checkout_security_attempts'',''SELECT''),(''checkout_security_attempts'',''INSERT''),(''checkout_security_attempts'',''DELETE'')\n  ) as required_access(table_name,privilege) loop\n    if not pg_catalog.has_table_privilege(''service_role'',''public.''||v_access.table_name,v_access.privilege)\n      then return 0; end if;\n  end loop;\n  foreach t in array array[''commercial_payment_events'',''commercial_payment_email_outbox'',\n    ''checkout_3ds_context'',''checkout_security_attempts''] loop\n    if pg_catalog.has_table_privilege(''anon'',''public.''||t,''SELECT,INSERT,UPDATE,DELETE'')\n      or pg_catalog.has_table_privilege(''authenticated'',''public.''||t,''SELECT,INSERT,UPDATE,DELETE'')\n      then return 0; end if;\n    -- Grants de coluna tambem podem abrir leitura/escrita sem grant da tabela.\n    -- PUBLIC e herdado nas consultas efetivas destes dois papeis.\n    foreach v_role in array array[''anon'',''authenticated''] loop\n      foreach v_privilege in array array[''SELECT'',''INSERT'',''UPDATE''] loop\n        if pg_catalog.has_any_column_privilege(v_role,''public.''||t,v_privilege)\n          then return 0; end if;\n      end loop;\n    end loop;\n  end loop;\n  -- Todas as colunas lidas/escritas pelas portas de compra/efeitos.\n  if exists (\n    select 1 from (values\n      (''commercial_orders'',''external_ref''),(''commercial_orders'',''business_id''),\n      (''commercial_orders'',''buyer_email''),(''commercial_orders'',''buyer_name''),\n      (''commercial_orders'',''buyer_whatsapp''),(''commercial_orders'',''legal_name''),\n      (''commercial_orders'',''cnpj''),(''commercial_orders'',''contractor_document_type''),\n      (''commercial_orders'',''status''),(''commercial_orders'',''origin''),\n      (''commercial_orders'',''payment_method''),(''commercial_orders'',''billing_period''),\n      (''commercial_orders'',''unit_count''),(''commercial_orders'',''total_cents''),\n      (''commercial_orders'',''provider_checkout_id''),(''commercial_orders'',''provider_checkout_url''),\n      (''commercial_orders'',''checkout_creation_started_at''),(''commercial_orders'',''payment_attempt_count''),\n      (''commercial_orders'',''payment_creation_started_at''),(''commercial_orders'',''provider_customer_id''),\n      (''commercial_orders'',''provider_charge_id''),(''commercial_orders'',''provider_subscription_id''),\n      (''commercial_orders'',''provider_first_due_date''),(''commercial_orders'',''provider_card_flow''),\n      (''commercial_orders'',''subscription_creation_started_at''),(''commercial_orders'',''provider_subscription_first_due_date''),\n      (''commercial_payment_events'',''provider_event_id''),(''commercial_payment_events'',''order_id''),\n      (''commercial_payment_events'',''provider_charge_id''),(''commercial_payment_events'',''provider_subscription_id''),\n      (''commercial_payment_events'',''event_type''),(''commercial_payment_events'',''amount_cents''),(''commercial_payment_events'',''due_date''),\n      (''commercial_payment_email_outbox'',''id''),(''commercial_payment_email_outbox'',''order_id''),\n      (''commercial_payment_email_outbox'',''provider_charge_id''),(''commercial_payment_email_outbox'',''payload''),\n      (''commercial_payment_email_outbox'',''status''),(''commercial_payment_email_outbox'',''provider_message_id''),\n      (''commercial_payment_email_outbox'',''updated_at''),\n      (''checkout_3ds_context'',''order_id''),(''checkout_3ds_context'',''payer_ip''),(''checkout_3ds_context'',''expires_at'')\n    ) as required(table_name,column_name)\n    where not exists (select 1 from pg_catalog.pg_attribute a\n      join pg_catalog.pg_class c on c.oid=a.attrelid\n      join pg_catalog.pg_namespace n on n.oid=c.relnamespace\n      where n.nspname=''public'' and c.relname=required.table_name\n        and a.attname=required.column_name and a.attnum>0 and not a.attisdropped)\n  ) then return 0; end if;\n  foreach sig in array array[\n    ''registrar_pedido_self_service(text,text,text,text,text,text,integer,text,text)'',\n    ''aprovar_pagamento_api_self_service(uuid,text,text,text,text,text,integer,date)'',\n    ''registrar_evento_financeiro_asaas(uuid,text,text,text,text,text,integer,date)'',\n    ''registrar_evento_inicial_3ds(uuid,text,text,text,text,integer,date)'',\n    ''reservar_assinatura_apos_3ds(uuid,date)'',\n    ''consumir_limite_checkout(text,text,text)'', ''documento_contratante_valido(text)'',\n    ''evento_asaas_impede_confirmacao(text)''\n  ] loop\n    f := pg_catalog.to_regprocedure(''public.''||sig);\n    if f is null then return 0; end if;\n    if pg_catalog.has_function_privilege(''anon'',f,''EXECUTE'')\n      or pg_catalog.has_function_privilege(''authenticated'',f,''EXECUTE'')\n      or not pg_catalog.has_function_privilege(''service_role'',f,''EXECUTE'')\n      or exists (select 1 from pg_catalog.pg_proc where oid=f and prosecdef)\n      then return 0; end if;\n  end loop;\n  -- Exige também a revisão de risco/RECEIVED, não apenas os nomes das RPCs.\n  foreach sig in array array[\n    ''aprovar_pagamento_api_self_service(uuid,text,text,text,text,text,integer,date)'',\n    ''registrar_evento_inicial_3ds(uuid,text,text,text,text,integer,date)'',\n    ''reservar_assinatura_apos_3ds(uuid,date)''\n  ] loop\n    if not exists(select 1 from pg_catalog.pg_proc\n      where oid=pg_catalog.to_regprocedure(''public.''||sig)\n        and pg_catalog.strpos(prosrc,''evento_asaas_impede_confirmacao'')>0)\n      then return 0; end if;\n  end loop;\n  if not public.evento_asaas_impede_confirmacao(''PAYMENT_REFUNDED'')\n    or not public.evento_asaas_impede_confirmacao(''PAYMENT_REPROVED_BY_RISK_ANALYSIS'')\n    or public.evento_asaas_impede_confirmacao(''PAYMENT_AUTHORIZED'') then return 0; end if;\n  -- Unicidades são as barreiras para replay, referência e envio duplicado.\n  if exists (select 1 from (values\n    (''commercial_orders'',''external_ref''),\n    (''commercial_orders'',''provider_charge_id''),(''commercial_orders'',''provider_subscription_id''),\n    (''commercial_events'',''source,external_event_id''),(''commercial_order_units'',''order_id,ordinal''),\n    (''commercial_payment_events'',''provider_event_id''),\n    (''commercial_payment_email_outbox'',''order_id,provider_charge_id''),\n    (''checkout_3ds_context'',''order_id'')\n  ) as required(table_name,columns) where not exists (\n    select 1 from pg_catalog.pg_index i\n      join pg_catalog.pg_class c on c.oid=i.indrelid\n      join pg_catalog.pg_namespace n on n.oid=c.relnamespace\n    where n.nspname=''public'' and c.relname=required.table_name and i.indisunique\n      and i.indisvalid and i.indpred is null and i.indexprs is null\n      and (select pg_catalog.string_agg(a.attname,'','' order by k.ord)\n        from pg_catalog.unnest(i.indkey::smallint[]) with ordinality k(attnum,ord)\n        join pg_catalog.pg_attribute a on a.attrelid=c.oid and a.attnum=k.attnum\n        where k.ord<=i.indnkeyatts)=required.columns\n  )) then return 0; end if;\n  if not public.documento_contratante_valido(''00000000191'')\n    or not public.documento_contratante_valido(''11222333000181'')\n    or public.documento_contratante_valido(''00000000192'') then return 0; end if;\n  return 1;\nexception when undefined_table or undefined_function or insufficient_privilege then return 0;\nend;\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"conferir_documento_contratante_gravado","owner":"postgres","signature":"conferir_documento_contratante_gravado()","definition":"CREATE OR REPLACE FUNCTION public.conferir_documento_contratante_gravado()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\r\ndeclare novo text; anterior text;\r\nbegin\r\n  novo:=to_jsonb(new)->>TG_ARGV[0];\r\n  if TG_OP=''UPDATE'' then\r\n    anterior:=to_jsonb(old)->>TG_ARGV[0];\r\n    if novo is not distinct from anterior then return new; end if;\r\n  end if;\r\n  if not public.documento_contratante_valido(novo) then raise exception ''documento_contratante_invalido''; end if;\r\n  return new;\r\nend;\r\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"consumir_limite_checkout","owner":"postgres","signature":"consumir_limite_checkout(text,text,text)","definition":"CREATE OR REPLACE FUNCTION public.consumir_limite_checkout(p_scope text, p_ip_hash text, p_contact_hash text)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\r\ndeclare\r\n  v_ip_count integer;\r\n  v_contact_count integer;\r\n  v_ip_limit integer;\r\n  v_contact_limit integer;\r\n  v_allowed boolean;\r\nbegin\r\n  if p_scope not in (''order'', ''payment'')\r\n      or p_ip_hash !~ ''^[0-9a-f]{64}$''\r\n      or p_contact_hash !~ ''^[0-9a-f]{64}$'' then\r\n    raise exception ''identificadores_de_seguranca_invalidos'';\r\n  end if;\r\n\r\n  perform pg_advisory_xact_lock(hashtextextended(\r\n    ''checkout-security:'' || p_scope || '':'' || p_ip_hash, 0\r\n  ));\r\n  perform pg_advisory_xact_lock(hashtextextended(\r\n    ''checkout-security:'' || p_scope || '':'' || p_contact_hash, 0\r\n  ));\r\n\r\n  delete from public.checkout_security_attempts where created_at < now() - interval ''7 days'';\r\n\r\n  select count(*) into v_ip_count from public.checkout_security_attempts\r\n   where scope = p_scope and ip_hash = p_ip_hash and outcome = ''allowed''\r\n     and created_at > now() - interval ''1 hour'';\r\n  select count(*) into v_contact_count from public.checkout_security_attempts\r\n   where scope = p_scope and contact_hash = p_contact_hash and outcome = ''allowed''\r\n     and created_at > now() - interval ''1 hour'';\r\n\r\n  v_ip_limit := case p_scope when ''order'' then 5 else 10 end;\r\n  v_contact_limit := case p_scope when ''order'' then 3 else 5 end;\r\n  v_allowed := v_ip_count < v_ip_limit and v_contact_count < v_contact_limit;\r\n\r\n  insert into public.checkout_security_attempts(scope, ip_hash, contact_hash, outcome)\r\n  values (p_scope, p_ip_hash, p_contact_hash,\r\n    case when v_allowed then ''allowed'' else ''blocked'' end);\r\n  return v_allowed;\r\nend;\r\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"documento_contratante_valido","owner":"postgres","signature":"documento_contratante_valido(text)","definition":"CREATE OR REPLACE FUNCTION public.documento_contratante_valido(p_documento text)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\r\ndeclare n integer; tamanho integer; pos integer; soma integer; peso integer; digito integer;\r\nbegin\r\n  if p_documento is null or p_documento !~ ''^([0-9]{11}|[0-9]{14})$''\r\n    or p_documento ~ ''^([0-9])\\1+$'' then return false; end if;\r\n  n:=length(p_documento);\r\n  for tamanho in (n-2)..(n-1) loop\r\n    soma:=0;\r\n    for pos in 1..tamanho loop\r\n      peso:=case when n=11 then tamanho+2-pos else ((tamanho-pos)%8)+2 end;\r\n      soma:=soma+substr(p_documento,pos,1)::integer*peso;\r\n    end loop;\r\n    if n=11 then\r\n      digito:=(soma*10)%11;\r\n      if digito=10 then digito:=0; end if;\r\n    else\r\n      digito:=case when soma%11<2 then 0 else 11-soma%11 end;\r\n    end if;\r\n    if substr(p_documento,tamanho+1,1)::integer<>digito then return false; end if;\r\n  end loop;\r\n  return true;\r\nend;\r\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"evento_asaas_impede_confirmacao","owner":"postgres","signature":"evento_asaas_impede_confirmacao(text)","definition":"CREATE OR REPLACE FUNCTION public.evento_asaas_impede_confirmacao(p_event_type text)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\r\n  select coalesce(p_event_type not in (\r\n    ''PAYMENT_CREATED'',''PAYMENT_UPDATED'',''PAYMENT_CONFIRMED'',''PAYMENT_RECEIVED'',\r\n    ''PAYMENT_AWAITING_RISK_ANALYSIS'',''PAYMENT_APPROVED_BY_RISK_ANALYSIS'',''PAYMENT_AUTHORIZED''\r\n  ), true)\r\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"registrar_conta_contratada","owner":"postgres","signature":"registrar_conta_contratada(uuid,uuid,text,text,text,text)","definition":"CREATE OR REPLACE FUNCTION public.registrar_conta_contratada(p_business_id uuid, p_connection_id uuid, p_external_id text, p_name text, p_currency text, p_page_id text)\n RETURNS uuid\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_account_id uuid;\n  v_unit_id uuid;\n  v_created_at timestamptz;\n  v_legacy_at timestamptz;\n  v_has_order boolean;\nbegin\n  if p_business_id is null or p_connection_id is null\n      or p_external_id is null or length(btrim(p_external_id)) < 3\n      or length(p_external_id) > 100\n      or p_page_id is null or length(btrim(p_page_id)) < 2\n      or length(p_page_id) > 100 then\n    raise exception ''conta ou pagina invalida'';\n  end if;\n\n  select created_at into v_created_at from public.businesses\n    where id = p_business_id for update;\n  if not found then raise exception ''negocio nao encontrado''; end if;\n  if not exists (select 1 from public.meta_connections\n      where id = p_connection_id and business_id = p_business_id) then\n    raise exception ''conexao nao pertence ao negocio'';\n  end if;\n\n  select exists (select 1 from public.commercial_orders\n    where business_id = p_business_id and status <> ''cancelled'')\n    into v_has_order;\n\n  if v_has_order then\n    select id into v_account_id from public.ad_accounts\n      where business_id = p_business_id and external_id = btrim(p_external_id);\n\n    if not exists (select 1 from public.commercial_order_units u\n        join public.commercial_orders o on o.id = u.order_id\n        where o.business_id = p_business_id and o.status = ''payment_approved''\n          and u.ad_account_id = v_account_id) then\n      select u.id into v_unit_id from public.commercial_order_units u\n        join public.commercial_orders o on o.id = u.order_id\n        where o.business_id = p_business_id and o.status = ''payment_approved''\n          and u.ad_account_id is null\n        order by o.created_at, u.ordinal limit 1 for update of u;\n      if v_unit_id is null then\n        if exists (select 1 from public.commercial_orders\n            where business_id = p_business_id\n              and status in (''awaiting_payment'', ''proof_received'')) then\n          raise exception ''pedido ainda nao aprovado'';\n        end if;\n        raise exception ''sem unidade contratada disponivel'';\n      end if;\n    end if;\n  else\n    select min(granted_at) into v_legacy_at from public.webapp_legacy_access;\n    if v_legacy_at is null or v_created_at > v_legacy_at then\n      raise exception ''negocio novo sem pedido aprovado'';\n    end if;\n  end if;\n\n  insert into public.ad_accounts(\n    business_id, meta_connection_id, external_id, name, currency,\n    ownership, status, is_active\n  ) values (\n    p_business_id, p_connection_id, btrim(p_external_id),\n    coalesce(nullif(btrim(p_name), ''''), btrim(p_external_id)),\n    nullif(btrim(p_currency), ''''), ''cliente'', ''ok'', true\n  ) on conflict (business_id, external_id) do update set\n    meta_connection_id = excluded.meta_connection_id,\n    name = excluded.name,\n    currency = excluded.currency,\n    ownership = ''cliente'', status = ''ok'', is_active = true\n  returning id into v_account_id;\n\n  if v_unit_id is not null then\n    update public.commercial_order_units set ad_account_id = v_account_id\n      where id = v_unit_id;\n  end if;\n  update public.meta_connections set meta_page_id = btrim(p_page_id)\n    where id = p_connection_id and business_id = p_business_id;\n  return v_account_id;\nend;\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"registrar_evento_financeiro_asaas","owner":"postgres","signature":"registrar_evento_financeiro_asaas(uuid,text,text,text,text,text,integer,date)","definition":"CREATE OR REPLACE FUNCTION public.registrar_evento_financeiro_asaas(p_order_id uuid, p_event_id text, p_charge_id text, p_subscription_id text, p_customer_id text, p_event_type text, p_amount_cents integer, p_due_date date)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\r\ndeclare\r\n  v_order public.commercial_orders%rowtype;\r\n  v_old public.commercial_payment_events%rowtype;\r\nbegin\r\n  if p_order_id is null or p_event_id is null or length(p_event_id) < 5\r\n      or p_charge_id is null or p_charge_id !~ ''^pay_[A-Za-z0-9]+$''\r\n      or p_customer_id is null or p_customer_id !~ ''^cus_[A-Za-z0-9]+$''\r\n      or p_amount_cents is null or p_amount_cents < 1 or p_due_date is null\r\n      or p_event_type not in (\r\n        ''PAYMENT_AWAITING_RISK_ANALYSIS'',''PAYMENT_APPROVED_BY_RISK_ANALYSIS'',''PAYMENT_REPROVED_BY_RISK_ANALYSIS'',''PAYMENT_AUTHORIZED'',''PAYMENT_CREATED'', ''PAYMENT_UPDATED'', ''PAYMENT_OVERDUE'',\r\n        ''PAYMENT_CONFIRMED'', ''PAYMENT_RECEIVED'', ''PAYMENT_CREDIT_CARD_CAPTURE_REFUSED'',\r\n        ''PAYMENT_CREDIT_CARD_THREE_D_SECURE_CHALLENGE_FAILED'',\r\n        ''PAYMENT_REFUND_IN_PROGRESS'', ''PAYMENT_PARTIALLY_REFUNDED'', ''PAYMENT_REFUNDED'',\r\n        ''PAYMENT_CHARGEBACK_REQUESTED'', ''PAYMENT_CHARGEBACK_DISPUTE'',\r\n        ''PAYMENT_AWAITING_CHARGEBACK_REVERSAL''\r\n      ) then return false; end if;\r\n\r\n  select * into v_order from public.commercial_orders\r\n    where id = p_order_id for update;\r\n  if not found or v_order.origin <> ''self_service''\r\n      or v_order.provider_checkout_id is not null\r\n      or v_order.status not in (''awaiting_payment'', ''payment_approved'')\r\n      or v_order.provider_customer_id is distinct from p_customer_id\r\n      or v_order.total_cents <> p_amount_cents then return false; end if;\r\n\r\n  if v_order.billing_period = ''monthly'' then\r\n    if v_order.payment_method <> ''asaas_card''\r\n        or v_order.provider_subscription_id is distinct from p_subscription_id\r\n        or p_subscription_id is null\r\n        or v_order.provider_first_due_date is null\r\n        or (p_due_date = v_order.provider_first_due_date\r\n            and v_order.provider_charge_id is not null\r\n            and p_charge_id <> v_order.provider_charge_id)\r\n        or (p_due_date > v_order.provider_first_due_date\r\n            and (v_order.status <> ''payment_approved''\r\n              or p_charge_id = v_order.provider_charge_id))\r\n        or p_due_date < v_order.provider_first_due_date then return false; end if;\r\n  elsif p_subscription_id is not null\r\n      or v_order.provider_charge_id is distinct from p_charge_id then\r\n    return false;\r\n  end if;\r\n\r\n  select * into v_old from public.commercial_payment_events\r\n    where provider_event_id = p_event_id;\r\n  if found then\r\n    return v_old.order_id = p_order_id\r\n      and v_old.provider_charge_id = p_charge_id\r\n      and v_old.provider_subscription_id is not distinct from p_subscription_id\r\n      and v_old.due_date = p_due_date and v_old.event_type = p_event_type\r\n      and v_old.amount_cents = p_amount_cents;\r\n  end if;\r\n  insert into public.commercial_payment_events(\r\n    provider_event_id, order_id, provider_charge_id, provider_subscription_id,\r\n    due_date, event_type, amount_cents\r\n  ) values (p_event_id, p_order_id, p_charge_id, p_subscription_id,\r\n    p_due_date, p_event_type, p_amount_cents);\r\n  return true;\r\nend;\r\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"registrar_evento_inicial_3ds","owner":"postgres","signature":"registrar_evento_inicial_3ds(uuid,text,text,text,text,integer,date)","definition":"CREATE OR REPLACE FUNCTION public.registrar_evento_inicial_3ds(p_order_id uuid, p_event_id text, p_charge_id text, p_customer_id text, p_event_type text, p_amount_cents integer, p_due_date date)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\r\ndeclare\r\n  v_order public.commercial_orders%rowtype;\r\n  v_old public.commercial_payment_events%rowtype;\r\n  v_event_order uuid;\r\nbegin\r\n  if p_event_id is null or length(p_event_id) < 5 or p_charge_id is null\r\n      or p_charge_id !~ ''^pay_[A-Za-z0-9]+$'' or p_customer_id is null\r\n      or p_customer_id !~ ''^cus_[A-Za-z0-9]+$'' or p_due_date is null\r\n      or p_amount_cents is null or p_amount_cents < 1 or p_event_type is null\r\n      or p_event_type not in (\r\n        ''PAYMENT_AWAITING_RISK_ANALYSIS'',''PAYMENT_APPROVED_BY_RISK_ANALYSIS'',''PAYMENT_REPROVED_BY_RISK_ANALYSIS'',''PAYMENT_AUTHORIZED'',''PAYMENT_CREATED'',''PAYMENT_UPDATED'',''PAYMENT_OVERDUE'',''PAYMENT_CONFIRMED'',''PAYMENT_RECEIVED'',\r\n        ''PAYMENT_CREDIT_CARD_CAPTURE_REFUSED'',''PAYMENT_CREDIT_CARD_THREE_D_SECURE_CHALLENGE_FAILED'',\r\n        ''PAYMENT_REFUND_IN_PROGRESS'',''PAYMENT_PARTIALLY_REFUNDED'',''PAYMENT_REFUNDED'',\r\n        ''PAYMENT_CHARGEBACK_REQUESTED'',''PAYMENT_CHARGEBACK_DISPUTE'',''PAYMENT_AWAITING_CHARGEBACK_REVERSAL''\r\n      ) then return false; end if;\r\n  select * into v_order from public.commercial_orders where id = p_order_id for update;\r\n  if not found or v_order.provider_card_flow <> ''initial_3ds''\r\n      or v_order.origin <> ''self_service'' or v_order.payment_method <> ''asaas_card''\r\n      or v_order.billing_period <> ''monthly'' or v_order.provider_checkout_id is not null\r\n      or v_order.status not in (''awaiting_payment'',''payment_approved'')\r\n      or v_order.provider_charge_id is distinct from p_charge_id\r\n      or v_order.provider_customer_id is distinct from p_customer_id\r\n      or v_order.total_cents <> p_amount_cents\r\n      or v_order.provider_first_due_date is distinct from p_due_date then return false; end if;\r\n  select * into v_old from public.commercial_payment_events where provider_event_id = p_event_id;\r\n  if found then\r\n    return v_old.order_id = p_order_id and v_old.provider_charge_id = p_charge_id\r\n      and v_old.provider_subscription_id is null and v_old.event_type = p_event_type\r\n      and v_old.amount_cents = p_amount_cents and v_old.due_date = p_due_date;\r\n  end if;\r\n  select order_id into v_event_order from public.commercial_events\r\n    where source = ''asaas'' and external_event_id = p_event_id;\r\n  if found then return false; end if;\r\n  insert into public.commercial_payment_events(provider_event_id,order_id,provider_charge_id,\r\n    provider_subscription_id,event_type,amount_cents,due_date)\r\n    values(p_event_id,p_order_id,p_charge_id,null,p_event_type,p_amount_cents,p_due_date);\r\n  -- Falha/abandono, retorno de callback e criacao de cobranca nunca abrem acesso.\r\n  -- Confirmacao recebida depois de estorno/contestacao nao reaprova a compra.\r\n  if p_event_type in (''PAYMENT_CONFIRMED'',''PAYMENT_RECEIVED'') and v_order.status = ''awaiting_payment''\r\n      and not exists(select 1 from public.commercial_payment_events e\r\n        where e.order_id = p_order_id and e.provider_charge_id = p_charge_id\r\n          and public.evento_asaas_impede_confirmacao(e.event_type)) then\r\n    insert into public.commercial_events(order_id,source,external_event_id,event_type)\r\n      values(p_order_id,''asaas'',p_event_id,p_event_type);\r\n    update public.commercial_orders set status = ''payment_approved'',\r\n      payment_approved_at = now(), updated_at = now() where id = p_order_id;\r\n  end if;\r\n  return true;\r\nend;\r\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"registrar_pedido_pix_assistido","owner":"postgres","signature":"registrar_pedido_pix_assistido(text,text,text,text,integer,text)","definition":"CREATE OR REPLACE FUNCTION public.registrar_pedido_pix_assistido(p_ref text, p_email text, p_legal_name text, p_cnpj text, p_unit_count integer, p_billing_period text)\n RETURNS uuid\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_email text := lower(btrim(p_email));\n  v_legal_name text := btrim(p_legal_name);\n  v_existing public.commercial_orders%rowtype;\n  v_business_id uuid;\n  v_order_id uuid;\n  v_total integer;\nbegin\n  if p_ref is null or p_ref !~ ''^[0-9a-f-]{36}$'' then\n    raise exception ''referencia invalida'';\n  end if;\n  if v_email is null or v_email !~ ''^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$''\n      or length(v_email) > 254 then\n    raise exception ''email invalido'';\n  end if;\n  if v_legal_name is null or length(v_legal_name) < 2 or length(v_legal_name) > 200\n      or p_cnpj is null or p_cnpj !~ ''^[0-9]{14}$''\n      or p_unit_count is null or p_unit_count not between 1 and 100\n      or p_billing_period not in (''monthly'', ''annual_upfront'') then\n    raise exception ''dados do pedido invalidos'';\n  end if;\n\n  select * into v_existing from public.commercial_orders where external_ref = p_ref;\n  if found then\n    if v_existing.buyer_email = v_email and v_existing.legal_name = v_legal_name\n        and v_existing.cnpj = p_cnpj and v_existing.unit_count = p_unit_count\n        and v_existing.billing_period = p_billing_period\n        and v_existing.payment_method = ''direct_pix'' then\n      return v_existing.id;\n    end if;\n    raise exception ''referencia ja utilizada'';\n  end if;\n\n  -- Uma compra adicional do mesmo comprador/CNPJ usa o negócio existente.\n  select business_id into v_business_id from public.commercial_orders\n    where buyer_email = v_email and cnpj = p_cnpj and business_id is not null\n      and status = ''payment_approved''\n    order by created_at desc limit 1;\n  if v_business_id is null then\n    insert into public.businesses(name, claim_email)\n      values (v_legal_name, v_email) returning id into v_business_id;\n  end if;\n\n  v_total := p_unit_count * case p_billing_period\n    when ''monthly'' then 50000 else 528000 end;\n  insert into public.commercial_orders(\n    external_ref, buyer_email, business_id, legal_name, cnpj,\n    declares_cnpj, sells_by_whatsapp, origin, payment_method,\n    billing_period, unit_price_cents, discount_percent, unit_count,\n    total_cents, status\n  ) values (\n    p_ref, v_email, v_business_id, v_legal_name, p_cnpj,\n    true, true, ''assisted'', ''direct_pix'', p_billing_period,\n    50000, case p_billing_period when ''monthly'' then 0 else 12 end,\n    p_unit_count, v_total, ''awaiting_payment''\n  ) returning id into v_order_id;\n\n  insert into public.commercial_order_units(order_id, ordinal)\n    select v_order_id, generate_series(1, p_unit_count);\n  return v_order_id;\nend;\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"registrar_pedido_self_service","owner":"postgres","signature":"registrar_pedido_self_service(text,text,text,text,text,text,integer,text,text)","definition":"CREATE OR REPLACE FUNCTION public.registrar_pedido_self_service(p_ref text, p_email text, p_buyer_name text, p_whatsapp text, p_legal_name text, p_cnpj text, p_unit_count integer, p_billing_period text, p_payment_method text)\n RETURNS uuid\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_email text := lower(btrim(p_email));\n  v_name text := btrim(p_legal_name);\n  v_buyer_name text := btrim(p_buyer_name);\n  v_existing public.commercial_orders%rowtype;\n  v_business_id uuid;\n  v_order_id uuid;\nbegin\n  -- cpf_cnpj_v0: validacao e identidade por pedido; sem fusao por contato/documento.\n  if p_ref is null or p_ref !~ ''^[0-9a-f-]{36}$''\n      or v_email is null or v_email !~ ''^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$''\n      or length(v_email) > 254 or v_buyer_name is null\n      or length(v_buyer_name) not between 2 and 120\n      or v_buyer_name !~ ''^[^[:space:]]+[[:space:]]+[^[:space:]]+''\n      or p_whatsapp is null or p_whatsapp !~ ''^[0-9]{10,13}$''\n      or v_name is null or length(v_name) < 2\n      or length(v_name) > 200 or p_cnpj is null or not public.documento_contratante_valido(p_cnpj)\n      or p_unit_count is null or p_unit_count not between 1 and 100\n      or p_billing_period not in (''monthly'', ''semiannual_upfront'', ''annual_upfront'')\n      or p_payment_method not in (''asaas_pix'', ''asaas_card'')\n      or (p_billing_period = ''monthly'' and p_payment_method <> ''asaas_card'') then\n    raise exception ''dados do pedido invalidos'';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(''commercial-order-ref:''||p_ref,0));\n  select * into v_existing from public.commercial_orders where external_ref = p_ref;\n  if found then\n    if v_existing.buyer_email = v_email and v_existing.buyer_name = v_buyer_name\n        and v_existing.buyer_whatsapp = p_whatsapp and v_existing.legal_name = v_name\n        and v_existing.cnpj = p_cnpj and v_existing.unit_count = p_unit_count\n        and v_existing.billing_period = p_billing_period\n        and v_existing.payment_method = p_payment_method\n        and v_existing.origin = ''self_service'' then\n      return v_existing.id;\n    end if;\n    raise exception ''referencia ja utilizada'';\n  end if;\n\n  insert into public.businesses(name, claim_email)\n      values (v_name, v_email) returning id into v_business_id;\n\n  insert into public.commercial_orders(\n    external_ref, buyer_email, buyer_name, buyer_whatsapp, business_id, legal_name, cnpj,\n    declares_cnpj, sells_by_whatsapp, origin, payment_method,\n    billing_period, unit_price_cents, discount_percent, unit_count,\n    total_cents, status\n  ) values (\n    p_ref, v_email, v_buyer_name, p_whatsapp, v_business_id, v_name, p_cnpj,\n    true, true, ''self_service'', p_payment_method,\n    p_billing_period, 50000, case p_billing_period\n      when ''monthly'' then 0 when ''semiannual_upfront'' then 5 else 12 end,\n    p_unit_count, p_unit_count * case p_billing_period\n      when ''monthly'' then 50000 when ''semiannual_upfront'' then 285000 else 528000 end,\n    ''awaiting_payment''\n  ) returning id into v_order_id;\n\n  insert into public.commercial_order_units(order_id, ordinal)\n    select v_order_id, generate_series(1, p_unit_count);\n  return v_order_id;\nend;\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"reservar_assinatura_apos_3ds","owner":"postgres","signature":"reservar_assinatura_apos_3ds(uuid,date)","definition":"CREATE OR REPLACE FUNCTION public.reservar_assinatura_apos_3ds(p_order_id uuid, p_next_due_date date)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\r\ndeclare v_order public.commercial_orders%rowtype;\r\nbegin\r\n  select * into v_order from public.commercial_orders where id = p_order_id for update;\r\n  if not found or v_order.provider_card_flow <> ''initial_3ds''\r\n      or v_order.status <> ''payment_approved''\r\n      or v_order.provider_subscription_id is not null\r\n      or v_order.subscription_creation_started_at is not null\r\n      or v_order.provider_charge_id is null or v_order.provider_customer_id is null\r\n      or v_order.provider_first_due_date is null or p_next_due_date is null\r\n      or p_next_due_date <> (v_order.provider_first_due_date + interval ''1 month'')::date\r\n      or p_next_due_date <= (now() at time zone ''America/Sao_Paulo'')::date\r\n      or not exists(select 1 from public.commercial_payment_events e where e.order_id = p_order_id\r\n        and e.provider_charge_id = v_order.provider_charge_id and e.event_type in (''PAYMENT_CONFIRMED'',''PAYMENT_RECEIVED''))\r\n      or exists(select 1 from public.commercial_payment_events e where e.order_id = p_order_id\r\n        and e.provider_charge_id = v_order.provider_charge_id\r\n        and public.evento_asaas_impede_confirmacao(e.event_type))\r\n      then return false; end if;\r\n  update public.commercial_orders set subscription_creation_started_at = now(),\r\n    provider_subscription_first_due_date = p_next_due_date, updated_at = now() where id = p_order_id;\r\n  return true;\r\nend;\r\n$function$\n"},{"acl":"{=X/postgres,anon=X/postgres,authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}","name":"set_updated_at","owner":"postgres","signature":"set_updated_at()","definition":"CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$function$\n"}]}'::jsonb,
