2","name":"fiscal_documents"},{"md5":"ba77a4cef6a948f0c6b81d69d7e3d9dc","name":"identidade_visual"},{"md5":"ae5b82efa044847a808e559d037d6e72","name":"itens_da_proposta"},{"md5":"0ad8a9c9f6746737d980f7b222779650","name":"leads_lp"},{"md5":"609a2669dcf881ba3c3195ac315dbb13","name":"meta_connections"},{"md5":"ba1d4b268ad55da2a9b0e1f36b628c8c","name":"metricas_diarias"},{"md5":"f1ffc43f68278acb94f3f700c7c88038","name":"metricas_diarias_arquivadas_20260924"},{"md5":"ba4512b10ad568575903fa283c2c88da","name":"metrics_daily"},{"md5":"3067dc7750cb3cad6e1c5627a68d3998","name":"narrativa_negocio"},{"md5":"0a9de8193aa55759f6beed7dcb4ee69c","name":"offers"},{"md5":"0e75d2feba7d80939f81806932d45127","name":"perguntas_apresentadas"},{"md5":"7eac7e3870ab7d9a2677226a5c4c380d","name":"pessoas_do_negocio"},{"md5":"762f5a9a42fcb87c4d76b12f5a0f45f1","name":"profiles"},{"md5":"b6afbc6e942209e9b7c38ce2cff20b6a","name":"propostas_de_perfil"},{"md5":"4f158837131e3df7ba42cce9243b7f1e","name":"respostas_do_dono"},{"md5":"16a77b48802c885d3dd4c4048791515e","name":"webapp_legacy_access"}]'::jsonb,
